WITH enriched AS (SELECT *, AVG(monthly_fee) OVER (PARTITION BY customer_id ORDER BY monthly_fee, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) monthly_fee_avg_5, LEAD(monthly_fee, 1) OVER (PARTITION BY status ORDER BY start_date, id) next_monthly_fee, ROW_NUMBER() OVER (PARTITION BY plan ORDER BY start_date DESC, id) event_seq FROM subscriptions) SELECT s.id, s.customer_id, s.plan, s.start_date, s.monthly_fee, s.status, s.monthly_fee_avg_5, s.next_monthly_fee, s.event_seq, CASE WHEN plan RLIKE '^(basic|standard)$' THEN 'GROUP_B' WHEN plan RLIKE '^(premium|enterprise)$' THEN 'PRIORITY' ELSE 'EXTENDED' END AS plan_zone, (SELECT MAX(t2.monthly_fee) FROM subscriptions t2 WHERE t2.customer_id = s.customer_id) AS max_subscription_monthly_fee FROM enriched s ORDER BY id DESC NULLS FIRST
